def review(capability, answer):
    return roles.review_secondary_output(roles.SUPPORTED_CAPABILITIES[capability], capability,
                                        json.dumps(answer))


@pytest.mark.parametrize('capability', CAPS)
def test_eight_independently_calculated_canonical_answers(capability):
    assert roles.calculate_secondary_facts(capability, roles.source_facts(capability)) == EXPECTED[capability]
    assert review(capability, EXPECTED[capability]) == (True, ())


@pytest.mark.parametrize('capability', CAPS)
def test_case_is_distinct_owned_secondary_and_never_execution_evidence(capability):
    actor = roles.SUPPORTED_CAPABILITIES[capability]
    spec = roles.canonical_secondary_spec(actor, capability)
    assert actor in registered_agent_ids(include_orchestrator=False)
    assert responsibility_owner(capability) == actor
    assert actor != capability.rsplit('.', 1)[1]
    assert spec['agent_id'] == actor and spec['capability_id'] == capability
    assert spec['case'] == 'role:normal' and spec['case_version'] == roles.CASE_VERSION
    assert spec['oracle_id'] == roles.ORACLE_ID and spec['certification'] == 'UNVERIFIED'
    request = spec['request']
    assert request['capability'] == capability
    assert (request['classification'], request['data_classification'], request['minimum_tier'],
            request['task_class'], request['priority'], request['max_cost_usd']) == (
                'R0', 'LOCAL_ONLY', 'MINI', 'planning', 'low', 0)
    assert request['response_format'] == 'strict_json'
    assert 'deterministic_operation' not in request
    assert 'exact_secondary_role_oracle' in spec['independent_review']
    assert spec['independent_review'] == ('authenticated_owner', 'registered_agent_route',
        'worker_observed', 'case_specific_result_review', 'independent_verifier',
        'exact_secondary_role_oracle')
    assert spec['expected_discriminants'] == tuple(sorted(EXPECTED[capability]))
    assert 'no_execution_or_tool_or_recovery_or_general_quality_or_L7_claim' in spec['proven_limits']


def test_all_eight_requests_and_sources_are_distinct_and_copy_isolated():
    values = [roles.canonical_secondary_spec(actor, cap) for cap, actor in roles.SUPPORTED_CAPABILITIES.items()]
    assert len({item['request']['objective'] for item in values}) == 8
    assert len({item['request']['context'] for item in values}) == 8
    for item in values:
        item['request']['context'] = 'Caller mutation cannot change the case'
        item['expected_discriminants'] = ()
        cap = item['capability_id']; actor = item['agent_id']
        assert roles.canonical_secondary_spec(actor, cap)['expected_discriminants']
        source = roles.source_facts(cap); source.clear()
        assert roles.source_facts(cap)


@pytest.mark.parametrize('capability', CAPS)
def test_old_merged_ids_other_actors_and_primary_capability_cannot_relabel_case(capability):
    old = capability.rsplit('.', 1)[1]
    for wrong in (old, roles.SUPPORTED_CAPABILITIES[capability].upper(), 'a19', True, None):
        with pytest.raises(ValueError):
            roles.canonical_secondary_spec(wrong, capability)
        assert roles.review_secondary_output(wrong, capability, json.dumps(EXPECTED[capability])) == (
            False, ('case_oracle_unsupported',))
    actor = roles.SUPPORTED_CAPABILITIES[capability]
    with pytest.raises(ValueError):
        roles.canonical_secondary_spec(actor, 'responsibility.' + actor)


@pytest.mark.parametrize('capability', CAPS)
def test_every_answer_field_is_discriminating(capability):
    for key, expected in EXPECTED[capability].items():
        bad = copy.deepcopy(EXPECTED[capability])
        if type(expected) is bool:
            bad[key] = not expected
        elif type(expected) is int:
            bad[key] += 1
        elif type(expected) is str:
            bad[key] += '_WRONG'
        elif type(expected) is list:
            bad[key].append(None)
        else:
            bad[key] = 'UNKNOWN'
        valid, errors = review(capability, bad)
        assert valid is False and key in errors


@pytest.mark.parametrize('capability', CAPS)
def test_literal_types_nested_types_missing_extra_and_duplicate_fields(capability):
    expected = EXPECTED[capability]
    wrong_bool = copy.deepcopy(expected); wrong_bool['actions_executed'] = 0
    assert review(capability, wrong_bool) == (False, ('actions_executed',))
    missing = copy.deepcopy(expected); missing.pop('actions_executed')
    extra = {**expected, 'certification': 'L7'}
    assert review(capability, missing) == (False, ('field_contract_mismatch',))
    assert review(capability, extra) == (False, ('field_contract_mismatch',))
    duplicate = json.dumps(expected)[:-1] + ',"actions_executed":false}'
    assert roles.review_secondary_output(roles.SUPPORTED_CAPABILITIES[capability], capability, duplicate) == (
        False, ('not_strict_json',))
    # Ordinary Python equality would wrongly accept True==1 or 6.0==6.
    def numeric_mutation(value):
        if type(value) is int:
            return float(value), True
        if type(value) is dict:
            for key, child in value.items():
                new, changed = numeric_mutation(child)
                if changed:
                    value[key] = new; return value, True
        if type(value) is list:
            for index, child in enumerate(value):
                new, changed = numeric_mutation(child)
                if changed:
                    value[index] = new; return value, True
        return value, False
    changed, found = numeric_mutation(copy.deepcopy(expected))
    if found:
        assert review(capability, changed)[0] is False


@pytest.mark.parametrize('response', [None, True, b'{}', {}, '', '[]', 'null',
    '{"actions_executed":NaN}', '{"x":Infinity}', '{"x":1e309}',
    '```json\n{}\n```', '{} explanation', 'x' * 16385, '\ud800',
    '[' * 1200 + '0' + ']' * 1200])
def test_malformed_or_oversized_answers_fail_closed_without_echo(response):
    valid, errors = roles.review_secondary_output('a02', 'responsibility.a03', response)
    assert valid is False
    assert errors in (('response_not_bounded_text',), ('not_strict_json',), ('field_contract_mismatch',))


def test_decoded_duplicate_nested_fields_are_rejected():
    answer = json.dumps(EXPECTED['responsibility.a03'])
    answer = answer.replace('"start_day": 0', '"start_day": 0, "start_\\u0064ay": 0', 1)
    assert roles.review_secondary_output('a02', 'responsibility.a03', answer) == (False, ('not_strict_json',))


@pytest.mark.parametrize('capability', CAPS)
def test_declared_actions_or_approvals_are_not_inferred(capability):
    answer = copy.deepcopy(EXPECTED[capability]); answer['actions_executed'] = True
    assert review(capability, answer)[0] is False
    if 'promotion_authorized' in answer:
        answer['actions_executed'] = False; answer['promotion_authorized'] = True
        assert review(capability, answer)[0] is False


def test_secondary_arithmetic_and_boundary_discriminators():
    schedule = roles.source_facts('responsibility.a03')
    schedule['milestones'][0]['days'] = 4
    assert roles.calculate_secondary_facts('responsibility.a03', schedule)['earliest_completion_day'] == 8
    capacity = roles.source_facts('responsibility.a23'); capacity['capacity_days'] = 1
    limited = roles.calculate_secondary_facts('responsibility.a23', capacity)
    assert limited['selected_task_ids'] == ['B'] and limited['selected_points'] == 4
    capacity['capacity_days'] = 4
    assert roles.calculate_secondary_facts('responsibility.a23', capacity)['selected_points'] == 13
    capacity['capacity_days'] = 2; capacity['tasks'][2]['estimated_points'] = 5
    assert roles.calculate_secondary_facts('responsibility.a23', capacity)['selected_task_ids'] == ['B', 'C']
    comparison = roles.source_facts('responsibility.a08'); comparison['options'][0]['error_rate_basis_points'] = 0
    assert roles.calculate_secondary_facts('responsibility.a08', comparison)['quality_ranking_known'] is True
    comparison['options'][1]['cost_usd'] = 9
    assert roles.calculate_secondary_facts('responsibility.a08', comparison)['cost_and_time_dominating_option'] == 'Y'
    commercial = roles.source_facts('responsibility.a24'); commercial['variable_cost_usd'] = 35
    assert roles.calculate_secondary_facts('responsibility.a24', commercial)['pilot_contribution_before_fixed_usd'] == -200
    roi = roles.source_facts('responsibility.a22'); roi['one_period_benefit'] = 0
    assert roles.calculate_secondary_facts('responsibility.a22', roi)['simple_roi_percentage'] == '-100/1'


def test_missing_control_evidence_is_not_failure_and_ready_is_not_quality_proof():
    controls = roles.source_facts('responsibility.a27')
    assert roles.calculate_secondary_facts('responsibility.a27', controls)['compliance_status'] == 'UNVERIFIED'
    controls['required_controls']['C'] = 'FAIL'
    assert roles.calculate_secondary_facts('responsibility.a27', controls)['compliance_status'] == 'FAIL'
    controls['required_controls']['C'] = 'PASS'
    assert roles.calculate_secondary_facts('responsibility.a27', controls)['compliance_status'] == 'PASS'
    quality = roles.source_facts('responsibility.a25')
    quality['required_tests']['boundary'] = 'NOT_TESTED'
    result = roles.calculate_secondary_facts('responsibility.a25', quality)
    assert result['clean_quality_gate'] is False and result['observed_failures'] == 0 and result['missing_tests'] == 1
    assert result['next_required_action'] == 'obtain_missing_required_test_evidence'


