@pytest.mark.parametrize('capability,mutate', BAD_SOURCE)
def test_bad_sources_cannot_launder_types_bounds_dependencies_or_authority(capability, mutate):
    source = roles.source_facts(capability); mutate(source)
    with pytest.raises(ValueError, match='SECONDARY_SOURCE_INVALID'):
        roles.calculate_secondary_facts(capability, source)


@pytest.mark.parametrize('capability', CAPS)
def test_source_schema_is_exact_and_calculation_does_not_mutate(capability):
    source = roles.source_facts(capability); original = copy.deepcopy(source)
    roles.calculate_secondary_facts(capability, source)
    assert source == original
    source['approved_by_agent'] = True
    with pytest.raises(ValueError):
        roles.calculate_secondary_facts(capability, source)


def test_registry_ownership_drift_denied_and_error_details_not_echoed(monkeypatch):
    from app import agent_registry
    original = agent_registry.agent_record
    monkeypatch.setattr(agent_registry, 'agent_record', lambda actor: {
        **original(actor), 'capability_requirements': ['responsibility.' + actor]})
    assert roles.review_secondary_output('a02', 'responsibility.a03', json.dumps(EXPECTED['responsibility.a03'])) == (
        False, ('case_oracle_unsupported',))
    with pytest.raises(ValueError):
        roles.canonical_secondary_spec('a02', 'responsibility.a03')
